 dict(id="p12", b="B12", day="Sat 28 Nov", slot="16:00", angle="brain & memory", arm="A", pred="medium", short="Word stops making sense",
  title="Why a word sounds weird when you repeat it 🔁", hook="Say one word for 15 seconds",
  desc="Say one word over and over and it starts to sound strange. In a classic study, people repeated a word out loud for 15 seconds (about 2–3 times a second); afterwards the word felt less meaningful. It's called semantic satiation – scientists think the brain's response to the word gets tired. Try it with 'milk'.",
  src="Lambert & Jakobovits (1960), Journal of Experimental Psychology – https://doi.org/10.1037/h0045624", tags="semantic satiation, why words sound weird when repeated, repeating a word, word loses meaning, brain facts, psychology facts, language psychology, try this",
  hashtags="#psychology #brain #language #brainfacts #shorts", pin="Try it: say your own name 30 times. What happened?",
  ig_hook="Say one word for 15 seconds… it loses its meaning 🔁", ig_body="People who repeated a word out loud felt it was less meaningful afterward. Milk. Milk. Milk. Scientists think your brain's response simply gets tired. Try it now.", ig_src="Lambert & Jakobovits (1960)", ig_tags="#psychology #brain #language #brainfacts"),
 dict(id="p13", b="B13", day="Sun 29 Nov", slot="12:00", angle="brain & money", arm="A", pred="medium", short="Losses hurt twice",
  title="Why losing money hurts you twice as much 💸", hook="Lose $100 or win $150?",
  desc="Would you flip a coin to lose $100 or win $150? Many people say no. A review of 607 estimates from about 150 studies found a loss weighs about twice as much as an equal gain (it varies a lot between people). It's called loss aversion: your brain guards what you have more than what you could get. Works the same in any currency. (Psychology research, not financial advice.)",
  src="Brown, Imai, Vieider & Camerer (2024), Journal of Economic Literature – https://doi.org/10.1257/jel.20221698", tags="loss aversion, why losing hurts more than winning, coin flip bet, money psychology, behavioral economics, kahneman, brain and money, psychology facts",
  hashtags="#psychology #moneypsychology #lossaversion #brain #shorts", pin="Would you take the bet: lose $100 or win $150?",
  ig_hook="Losing money hurts about twice as much as winning feels good 💸", ig_body="Lose $100 or win $150 on a coin flip? Many say no. Across ~150 studies, the win had to be about twice the loss. Your brain guards what you have.", ig_src="Brown, Imai, Vieider & Camerer (2024)", ig_tags="#psychology #moneypsychology #lossaversion #brain"),
